{
  "headline": "Octreotide acetate is not on FDA's shortage list; one registered plant for a labeled product was classified OAI on 2026-04-17",
  "headline_cites": ["D4", "E14", "E12"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include octreotide acetate as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "A product label for octreotide acetate 500 ug/mL, 1 mL vial lists USV Private Limited (FEI 3004086192) as the manufacturing and packaging plant.",
      "cites": ["E14"]
    },
    {
      "text": "FDA inspection 1321638 at that plant ended on 2026-04-17 and was classified OAI, with the classification known on 2026-07-16.",
      "cites": ["E12"]
    },
    {
      "text": "The same plant received a Warning Letter on 2017-03-10 and prior OAI classifications in 2016 and 2022.",
      "cites": ["E8", "E11", "E13"]
    },
    {
      "text": "Current inventory across three Corvale sites ranges from 17.2 to 25.6 days on hand for the 500 ug/mL, 1 mL presentation.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The rule-based best option is to buy from Fresenius Kabi USA, LLC, which is not on FDA's shortage list today, though its label names no plant we could place.",
      "cites": ["D5"]
    }
  ]
}
